WITH inner_cte AS ( SELECT ata.ACADEMIC_YEAR, ata.ACADEMIC_YEAR_DESC, STDDEV(lso.NUM_ENROLLED_STUDENTS) AS stddev_num_enrolled_students FROM LIBRARY_SUBJECT_OFFERED lso JOIN ACADEMIC_TERMS_ALL ata ON lso.TERM_CODE = ata.TERM_CODE JOIN COURSE_CATALOG_SUBJECT_OFFERED ccso ON lso.TERM_CODE = ccso.TERM_CODE AND lso.SUBJECT_ID = ccso.SUBJECT_ID WHERE ccso.DEPARTMENT_NAME = 'Mathematics' AND ccso.IS_OFFERED_FALL_TERM = 'Y' GROUP BY ata.ACADEMIC_YEAR, ata.ACADEMIC_YEAR_DESC HAVING COUNT(*) > 5 ) SELECT ic.ACADEMIC_YEAR, ic.ACADEMIC_YEAR_DESC, ic.stddev_num_enrolled_students, ls.SUBJECT_ID AS Top_Subject_ID, ls.SUBJECT_TITLE AS Top_Subject_Title, ls.NUM_ENROLLED_STUDENTS AS Top_Enrollment FROM inner_cte ic LEFT JOIN ( SELECT ata.ACADEMIC_YEAR, lso.SUBJECT_ID, lso.SUBJECT_TITLE, lso.NUM_ENROLLED_STUDENTS, ROW_NUMBER() OVER (PARTITION BY ata.ACADEMIC_YEAR ORDER BY lso.NUM_ENROLLED_STUDENTS DESC) AS rn FROM LIBRARY_SUBJECT_OFFERED lso JOIN ACADEMIC_TERMS_ALL ata ON lso.TERM_CODE = ata.TERM_CODE JOIN COURSE_CATALOG_SUBJECT_OFFERED ccso ON lso.TERM_CODE = ccso.TERM_CODE AND lso.SUBJECT_ID = ccso.SUBJECT_ID WHERE ccso.DEPARTMENT_NAME = 'Mathematics' AND ccso.IS_OFFERED_FALL_TERM = 'Y' ) ls ON ic.ACADEMIC_YEAR = ls.ACADEMIC_YEAR AND ls.rn = 1 ORDER BY ic.stddev_num_enrolled_students DESC LIMIT 10;